43: // Next pulls the next batch from the iterator. Returns io.EOF when iteration is done.
44: func (it *Iterator) Next() (*OpBatch, error) {
45: 	if it.pullNext == nil {
46: 		next, stop := iter.Pull2(it.Seq())
47: 		it.pullNext = next
48: 		it.pullStop = stop
49: 	}
50: 	batch, err, ok := it.pullNext()
51: 	if !ok {
52: 		return nil, io.EOF
53: 	}
54: 	return batch, err
55: }
