9: // AssignSubsystem returns the name of the subsystem that the given file belongs to.
10: // It iterates through the subsystems and returns the first one where a glob matches the file path.
11: // Returns an empty string if no subsystem matches.
12: func (c RepoConfig) AssignSubsystem(filePath string) string {
13: 	var names []string
14: 	for name := range c.Subsystems {
15: 		names = append(names, name)
16: 	}
17: 	sort.Strings(names)
18: 
19: 	for _, name := range names {
20: 		subsystem := c.Subsystems[name]
21: 		for _, pattern := range subsystem.Globs {
22: 			matched, err := filepath.Match(pattern, filePath)
23: 			if err == nil && matched {
24: 				return name
25: 			}
26: 			
27: 			// Support ** for recursive directory matching
28: 			if strings.HasSuffix(pattern, "/**") {
29: 				prefix := strings.TrimSuffix(pattern, "/**")
30: 				if strings.HasPrefix(filePath, prefix+"/") {
31: 					return name
32: 				}
33: 			}
34: 		}
35: 	}
36: 	return ""
37: }
