package config

import (
	"context"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/dossiers"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/ops"
	"gopkg.in/yaml.v3"
)

// DeclaredScope represents a hand-declared scope in config.yaml.
type DeclaredScope struct {
	Name        string   `json:"name" yaml:"name"`
	Keywords    []string `json:"keywords,omitempty" yaml:"keywords,omitempty"`
	ToolNames   []string `json:"tool_names,omitempty" yaml:"tool_names,omitempty"`
	Commands    []string `json:"commands,omitempty" yaml:"commands,omitempty"`
	Description string   `json:"description,omitempty" yaml:"description,omitempty"`
}

// UnmarshalYAML implements custom unmarshaling for DeclaredScope to support alternate field spellings.
func (s *DeclaredScope) UnmarshalYAML(value *yaml.Node) error {
	type rawDeclaredScope struct {
		Name         string   `yaml:"name"`
		Keywords     []string `yaml:"keywords"`
		ToolNames    []string `yaml:"tool_names"`
		ToolNamesAlt []string `yaml:"toolNames"`
		Tools        []string `yaml:"tools"`
		Commands     []string `yaml:"commands"`
		Description  string   `yaml:"description"`
	}
	var raw rawDeclaredScope
	if err := value.Decode(&raw); err != nil {
		return err
	}
	s.Name = raw.Name
	s.Keywords = raw.Keywords
	s.ToolNames = raw.ToolNames
	if len(s.ToolNames) == 0 && len(raw.ToolNamesAlt) > 0 {
		s.ToolNames = raw.ToolNamesAlt
	}
	if len(s.ToolNames) == 0 && len(raw.Tools) > 0 {
		s.ToolNames = raw.Tools
	}
	s.Commands = raw.Commands
	s.Description = raw.Description
	return nil
}

// ScopeConfig contains hand-declared scopes organized by category.
type ScopeConfig struct {
	Topics     []DeclaredScope `json:"topics,omitempty" yaml:"topics,omitempty"`
	Externals  []DeclaredScope `json:"externals,omitempty" yaml:"externals,omitempty"`
	Procedures []DeclaredScope `json:"procedures,omitempty" yaml:"procedures,omitempty"`
}

// LoadScopeConfig reads from config.yaml under a scopes: key.
// If the scopes: key is missing or the file is empty, it returns an empty config (not an error).
func LoadScopeConfig(configPath string) (*ScopeConfig, error) {
	if configPath == "" {
		configPath = filepath.Join(".memory", "config.yaml")
	}

	target := configPath
	if fi, err := os.Stat(target); err == nil && fi.IsDir() {
		candidate := filepath.Join(target, ".memory", "config.yaml")
		if _, err := os.Stat(candidate); err == nil {
			target = candidate
		} else {
			target = filepath.Join(target, "config.yaml")
		}
	}

	data, err := os.ReadFile(target)
	if err != nil {
		if os.IsNotExist(err) {
			return &ScopeConfig{}, nil
		}
		return nil, fmt.Errorf("reading config file %s: %w", target, err)
	}

	if len(strings.TrimSpace(string(data))) == 0 {
		return &ScopeConfig{}, nil
	}

	var root struct {
		Scopes *ScopeConfig `yaml:"scopes"`
	}
	if err := yaml.Unmarshal(data, &root); err != nil {
		return nil, fmt.Errorf("parsing scope config %s: %w", target, err)
	}

	if root.Scopes == nil {
		return &ScopeConfig{}, nil
	}

	return root.Scopes, nil
}

// ModuleScope represents a derived module scope with path globs and symbols.
type ModuleScope struct {
	Name      string   `json:"name" yaml:"name"`
	PathGlobs []string `json:"path_globs,omitempty" yaml:"path_globs,omitempty"`
	Symbols   []string `json:"symbols,omitempty" yaml:"symbols,omitempty"`
}

// DeriveModuleScopes derives module scopes from a list of file path anchors
// by rolling up directories with <= 2 files to the nearest meaningful parent directory.
func DeriveModuleScopes(anchors []string) []ModuleScope {
	if len(anchors) == 0 {
		return nil
	}

	type fileInfo struct {
		filePath string
		symbol   string
	}

	dirFiles := make(map[string][]fileInfo)
	for _, anchor := range anchors {
		anchor = strings.TrimSpace(anchor)
		if anchor == "" {
			continue
		}

		var sym string
		p := anchor
		if idx := strings.Index(p, "#"); idx != -1 {
			sym = p[idx+1:]
			p = p[:idx]
		}

		p = filepath.ToSlash(filepath.Clean(p))
		p = strings.TrimPrefix(p, "./")
		p = strings.TrimPrefix(p, "/")
		if p == "" || p == "." {
			continue
		}

		dir := path.Dir(p)
		dirFiles[dir] = append(dirFiles[dir], fileInfo{filePath: p, symbol: sym})
	}

	if len(dirFiles) == 0 {
		return nil
	}

	// Helper to check if parent is meaningful to roll up into
	isMeaningfulParent := func(p string) bool {
		p = strings.TrimPrefix(p, "./")
		p = strings.TrimPrefix(p, "/")
		if p == "" || p == "." || p == "/" || p == "internal" || p == "cmd" {
			return false
		}
		return true
	}

	// Sort directories by depth descending to process bottom-up
	for {
		changed := false
		dirs := make([]string, 0, len(dirFiles))
		for d := range dirFiles {
			dirs = append(dirs, d)
		}
		sort.Slice(dirs, func(i, j int) bool {
			depthI := strings.Count(dirs[i], "/")
			depthJ := strings.Count(dirs[j], "/")
			if depthI != depthJ {
				return depthI > depthJ
			}
			return dirs[i] < dirs[j]
		})

		for _, d := range dirs {
			files := dirFiles[d]
			// Count distinct file paths
			distinct := make(map[string]bool)
			for _, fi := range files {
				distinct[fi.filePath] = true
			}
			if len(distinct) <= 2 {
				parent := path.Dir(d)
				if isMeaningfulParent(parent) {
					dirFiles[parent] = append(dirFiles[parent], files...)
					delete(dirFiles, d)
					changed = true
					break
				}
			}
		}

		if !changed {
			break
		}
	}

	// Convert directories to module scopes
	scopeMap := make(map[string]*ModuleScope)
	for dir, files := range dirFiles {
		scopeName := dirToScopeName(dir)
		if scopeName == "" {
			continue
		}

		ms, ok := scopeMap[scopeName]
		if !ok {
			ms = &ModuleScope{
				Name:      scopeName,
				PathGlobs: []string{},
				Symbols:   []string{},
			}
			scopeMap[scopeName] = ms
		}

		for _, fi := range files {
			ms.PathGlobs = append(ms.PathGlobs, fi.filePath)
			if fi.symbol != "" {
				ms.Symbols = append(ms.Symbols, fi.symbol)
			}
		}
	}

	var result []ModuleScope
	for _, ms := range scopeMap {
		ms.PathGlobs = uniqueSorted(ms.PathGlobs)
		ms.Symbols = uniqueSorted(ms.Symbols)
		result = append(result, *ms)
	}

	sort.Slice(result, func(i, j int) bool {
		return result[i].Name < result[j].Name
	})

	return result
}

func dirToScopeName(dir string) string {
	dir = filepath.ToSlash(filepath.Clean(dir))
	dir = strings.TrimPrefix(dir, "./")
	dir = strings.TrimPrefix(dir, "/")
	if dir == "" || dir == "." {
		return "root"
	}

	var name string
	if strings.HasPrefix(dir, "internal/") {
		name = strings.TrimPrefix(dir, "internal/")
	} else if strings.HasPrefix(dir, "cmd/") {
		name = dir
	} else {
		name = dir
	}

	// Convert underscores to hyphens for kebab-case scope names
	parts := strings.Split(name, "/")
	for i, p := range parts {
		parts[i] = strings.ReplaceAll(p, "_", "-")
	}
	return strings.Join(parts, "/")
}

func uniqueSorted(strs []string) []string {
	seen := make(map[string]bool)
	var res []string
	for _, s := range strs {
		s = strings.TrimSpace(s)
		if s != "" && !seen[s] {
			seen[s] = true
			res = append(res, s)
		}
	}
	sort.Strings(res)
	if res == nil {
		return []string{}
	}
	return res
}

// AliasMap maps old scope names to new ones (derived from split ops).
type AliasMap struct {
	Aliases    map[string]string   `json:"aliases"`
	Targets    map[string][]string `json:"targets"`
	EntryMoves map[string]string   `json:"entry_moves,omitempty"`
}

// NewAliasMap initializes an empty AliasMap.
func NewAliasMap() *AliasMap {
	return &AliasMap{
		Aliases:    make(map[string]string),
		Targets:    make(map[string][]string),
		EntryMoves: make(map[string]string),
	}
}

// AddSplit registers a split mapping from oldScope to newDossiers.
func (a *AliasMap) AddSplit(oldScope string, newDossiers []string) {
	if a.Aliases == nil {
		a.Aliases = make(map[string]string)
	}
	if a.Targets == nil {
		a.Targets = make(map[string][]string)
	}
	if len(newDossiers) > 0 {
		a.Targets[oldScope] = append([]string(nil), newDossiers...)
		a.Aliases[oldScope] = newDossiers[0]
	}
}

// BuildAliasMap iterates all ops from opsReader and builds an AliasMap from split ops.
func BuildAliasMap(opsReader *ops.Reader, ctx context.Context) (*AliasMap, error) {
	aliasMap := NewAliasMap()
	if opsReader == nil {
		return aliasMap, nil
	}
	if ctx == nil {
		ctx = context.Background()
	}

	for batch, err := range opsReader.Iterate(ctx) {
		if err != nil {
			return nil, err
		}
		if batch == nil {
			continue
		}
		for _, op := range batch.Ops {
			if op.Type == ops.OpSplit {
				oldScope := strings.TrimSpace(op.DossierScope)
				if oldScope == "" {
					continue
				}

				var newDossiers []string
				if raw, ok := op.Fields["new_dossiers"]; ok {
					switch v := raw.(type) {
					case []string:
						for _, s := range v {
							s = strings.TrimSpace(s)
							if s != "" {
								newDossiers = append(newDossiers, s)
							}
						}
					case []any:
						for _, item := range v {
							if s, ok := item.(string); ok {
								s = strings.TrimSpace(s)
								if s != "" {
									newDossiers = append(newDossiers, s)
								}
							}
						}
					}
				}

				if len(newDossiers) > 0 {
					aliasMap.Targets[oldScope] = newDossiers
					aliasMap.Aliases[oldScope] = newDossiers[0]
				}

				if rawMoves, ok := op.Fields["entry_moves"]; ok {
					switch moves := rawMoves.(type) {
					case map[string]string:
						for eID, targetScope := range moves {
							aliasMap.EntryMoves[eID] = targetScope
						}
					case map[string]any:
						for eID, val := range moves {
							if targetScope, ok := val.(string); ok {
								aliasMap.EntryMoves[eID] = targetScope
							}
						}
					}
				}
			}
		}
	}

	return aliasMap, nil
}

// Resolve follows the alias chain for a scope name, preventing infinite loops with max depth 10.
func (a *AliasMap) Resolve(scope string) string {
	if a == nil || a.Aliases == nil || scope == "" {
		return scope
	}
	curr := scope
	for depth := 0; depth < 10; depth++ {
		next, ok := a.Aliases[curr]
		if !ok || next == "" || next == curr {
			return curr
		}
		curr = next
	}
	return curr
}

// ScopeResolver combines declared scopes, derived module scopes, and aliases.
type ScopeResolver struct {
	config  *ScopeConfig
	modules []ModuleScope
	aliases *AliasMap
}

// NewScopeResolver creates a ScopeResolver.
func NewScopeResolver(config *ScopeConfig, modules []ModuleScope, aliases *AliasMap) *ScopeResolver {
	if config == nil {
		config = &ScopeConfig{}
	}
	if aliases == nil {
		aliases = NewAliasMap()
	}
	return &ScopeResolver{
		config:  config,
		modules: modules,
		aliases: aliases,
	}
}

// ResolveScope resolves anchors and keywords to the best matching scope name.
func (r *ScopeResolver) ResolveScope(anchors []string, keywords []string) string {
	// 1. First check aliases
	if r.aliases != nil {
		for _, a := range anchors {
			if resolved := r.aliases.Resolve(a); resolved != a && resolved != "" {
				return resolved
			}
		}
		for _, kw := range keywords {
			if resolved := r.aliases.Resolve(kw); resolved != kw && resolved != "" {
				return resolved
			}
		}
	}

	// 2. Try to match anchors against module scopes (path prefix match)
	var bestModuleScope string
	var bestModuleScore int
	for _, anchor := range anchors {
		anchor = strings.TrimSpace(anchor)
		if anchor == "" {
			continue
		}
		if idx := strings.Index(anchor, "#"); idx != -1 {
			anchor = anchor[:idx]
		}
		p := filepath.ToSlash(filepath.Clean(anchor))
		p = strings.TrimPrefix(p, "./")
		p = strings.TrimPrefix(p, "/")
		pNorm := strings.ReplaceAll(p, "_", "-")

		for _, m := range r.modules {
			score := 0
			// Check direct path globs
			for _, g := range m.PathGlobs {
				gClean := filepath.ToSlash(filepath.Clean(g))
				gClean = strings.TrimPrefix(gClean, "./")
				gClean = strings.TrimPrefix(gClean, "/")
				if p == gClean {
					if len(gClean) > score {
						score = len(gClean) + 10
					}
				} else if strings.HasPrefix(p, gClean+"/") {
					if len(gClean) > score {
						score = len(gClean) + 5
					}
				}
			}

			// Check module name prefix
			mName := m.Name
			if pNorm == mName || strings.HasPrefix(pNorm, mName+"/") {
				if len(mName) > score {
					score = len(mName)
				}
			}
			if strings.HasPrefix(pNorm, "internal/"+mName+"/") || pNorm == "internal/"+mName {
				if len(mName) > score {
					score = len(mName)
				}
			}
			if strings.HasPrefix(pNorm, "cmd/"+mName+"/") || pNorm == "cmd/"+mName {
				if len(mName) > score {
					score = len(mName)
				}
			}

			if score > bestModuleScore {
				bestModuleScore = score
				bestModuleScope = m.Name
			}
		}
	}

	if bestModuleScope != "" {
		if r.aliases != nil {
			return r.aliases.Resolve(bestModuleScope)
		}
		return bestModuleScope
	}

	// 3. Try to match keywords against declared topics, externals, procedures
	var bestDeclaredScope string
	var bestDeclaredScore int

	checkDeclared := func(scopes []DeclaredScope) {
		for _, s := range scopes {
			score := 0
			sNameLower := strings.ToLower(s.Name)
			sDescLower := strings.ToLower(s.Description)

			for _, kw := range keywords {
				kwLower := strings.ToLower(strings.TrimSpace(kw))
				if kwLower == "" {
					continue
				}

				if kwLower == sNameLower {
					score += 15
				} else if strings.Contains(sNameLower, kwLower) {
					score += 6
				}

				for _, k := range s.Keywords {
					kLower := strings.ToLower(strings.TrimSpace(k))
					if kwLower == kLower {
						score += 10
					} else if strings.Contains(kLower, kwLower) {
						score += 4
					}
				}

				for _, tool := range s.ToolNames {
					toolLower := strings.ToLower(strings.TrimSpace(tool))
					if kwLower == toolLower {
						score += 10
					} else if strings.Contains(toolLower, kwLower) {
						score += 4
					}
				}

				for _, cmd := range s.Commands {
					cmdLower := strings.ToLower(strings.TrimSpace(cmd))
					if kwLower == cmdLower || strings.HasPrefix(kwLower, cmdLower) {
						score += 10
					} else if strings.Contains(cmdLower, kwLower) {
						score += 4
					}
				}

				if sDescLower != "" && strings.Contains(sDescLower, kwLower) {
					score += 1
				}
			}

			if score > bestDeclaredScore {
				bestDeclaredScore = score
				bestDeclaredScope = s.Name
			}
		}
	}

	if r.config != nil {
		checkDeclared(r.config.Topics)
		checkDeclared(r.config.Externals)
		checkDeclared(r.config.Procedures)
	}

	if bestDeclaredScope != "" {
		if r.aliases != nil {
			return r.aliases.Resolve(bestDeclaredScope)
		}
		return bestDeclaredScope
	}

	return ""
}

// AllScopes returns all known scope names (declared + derived + from aliases), deduplicated and sorted.
func (r *ScopeResolver) AllScopes() []string {
	seen := make(map[string]bool)
	var all []string
	add := func(name string) {
		name = strings.TrimSpace(name)
		if name != "" && !seen[name] {
			seen[name] = true
			all = append(all, name)
		}
	}

	if r.config != nil {
		for _, s := range r.config.Topics {
			add(s.Name)
		}
		for _, s := range r.config.Externals {
			add(s.Name)
		}
		for _, s := range r.config.Procedures {
			add(s.Name)
		}
	}

	for _, m := range r.modules {
		add(m.Name)
	}

	if r.aliases != nil {
		for oldScope, newScope := range r.aliases.Aliases {
			add(oldScope)
			add(newScope)
		}
		for oldScope, targets := range r.aliases.Targets {
			add(oldScope)
			for _, t := range targets {
				add(t)
			}
		}
	}

	sort.Strings(all)
	return all
}

// ScopeKind returns the DossierKind for a given scope name.
func (r *ScopeResolver) ScopeKind(scope string) dossiers.DossierKind {
	if r.config != nil {
		for _, s := range r.config.Topics {
			if s.Name == scope {
				return dossiers.DossierKindTopic
			}
		}
		for _, s := range r.config.Externals {
			if s.Name == scope {
				return dossiers.DossierKindExternal
			}
		}
		for _, s := range r.config.Procedures {
			if s.Name == scope {
				return dossiers.DossierKindProcedure
			}
		}
	}
	for _, m := range r.modules {
		if m.Name == scope {
			return dossiers.DossierKindModule
		}
	}
	return dossiers.DossierKindModule
}

