package config

import (
	"context"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/dossiers"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/ops"
)

func init() {
	// If REPO_MEMORY_DATA_DIR is set in the test environment without ending in repo-memory,
	// unset it so that existing config_test.go tests in the package do not fail.
	if v := os.Getenv("REPO_MEMORY_DATA_DIR"); v != "" && !strings.HasSuffix(v, "repo-memory") {
		_ = os.Unsetenv("REPO_MEMORY_DATA_DIR")
	}
}

func TestLoadScopeConfig(t *testing.T) {
	yamlContent := `
scopes:
  topics:
    - name: persistence-and-sqlite
      keywords:
        - persistence
        - sqlite
        - concurrency
      description: "Persistence and SQLite storage"
  externals:
    - name: antigravity-hooks
      keywords:
        - antigravity
        - hooks
      tool_names:
        - run_command
        - view_file
      description: "Antigravity hooks integration"
  procedures:
    - name: release
      keywords:
        - release
        - publish
      commands:
        - git tag
        - goreleaser
      description: "Release procedures"
`
	tmpDir := t.TempDir()
	cfgPath := filepath.Join(tmpDir, "config.yaml")
	if err := os.WriteFile(cfgPath, []byte(yamlContent), 0o644); err != nil {
		t.Fatalf("failed to write test yaml: %v", err)
	}

	cfg, err := LoadScopeConfig(cfgPath)
	if err != nil {
		t.Fatalf("LoadScopeConfig failed: %v", err)
	}
	if cfg == nil {
		t.Fatal("expected non-nil ScopeConfig")
	}

	// Verify Topics
	if len(cfg.Topics) != 1 {
		t.Fatalf("expected 1 topic, got %d", len(cfg.Topics))
	}
	top := cfg.Topics[0]
	if top.Name != "persistence-and-sqlite" {
		t.Errorf("topic name: got %q, want %q", top.Name, "persistence-and-sqlite")
	}
	if !reflect.DeepEqual(top.Keywords, []string{"persistence", "sqlite", "concurrency"}) {
		t.Errorf("topic keywords: got %v", top.Keywords)
	}
	if top.Description != "Persistence and SQLite storage" {
		t.Errorf("topic description: got %q", top.Description)
	}

	// Verify Externals
	if len(cfg.Externals) != 1 {
		t.Fatalf("expected 1 external, got %d", len(cfg.Externals))
	}
	ext := cfg.Externals[0]
	if ext.Name != "antigravity-hooks" {
		t.Errorf("external name: got %q, want %q", ext.Name, "antigravity-hooks")
	}
	if !reflect.DeepEqual(ext.ToolNames, []string{"run_command", "view_file"}) {
		t.Errorf("external tool_names: got %v", ext.ToolNames)
	}

	// Verify Procedures
	if len(cfg.Procedures) != 1 {
		t.Fatalf("expected 1 procedure, got %d", len(cfg.Procedures))
	}
	proc := cfg.Procedures[0]
	if proc.Name != "release" {
		t.Errorf("procedure name: got %q, want %q", proc.Name, "release")
	}
	if !reflect.DeepEqual(proc.Commands, []string{"git tag", "goreleaser"}) {
		t.Errorf("procedure commands: got %v", proc.Commands)
	}
}

func TestLoadScopeConfig_MissingScopesKey(t *testing.T) {
	yamlContent := `
subsystems:
  core-infrastructure:
    description: "Config and data directory layout"
    globs:
      - "internal/core/config/**"
`
	tmpDir := t.TempDir()
	cfgPath := filepath.Join(tmpDir, "config.yaml")
	if err := os.WriteFile(cfgPath, []byte(yamlContent), 0o644); err != nil {
		t.Fatalf("failed to write test yaml: %v", err)
	}

	cfg, err := LoadScopeConfig(cfgPath)
	if err != nil {
		t.Fatalf("LoadScopeConfig should not return error for missing scopes key: %v", err)
	}
	if cfg == nil {
		t.Fatal("expected non-nil ScopeConfig")
	}
	if len(cfg.Topics) != 0 || len(cfg.Externals) != 0 || len(cfg.Procedures) != 0 {
		t.Errorf("expected empty ScopeConfig, got topics=%d, externals=%d, procedures=%d",
			len(cfg.Topics), len(cfg.Externals), len(cfg.Procedures))
	}

	// Test empty file returns empty config
	emptyPath := filepath.Join(tmpDir, "empty.yaml")
	if err := os.WriteFile(emptyPath, []byte(""), 0o644); err != nil {
		t.Fatalf("failed to write empty yaml: %v", err)
	}
	emptyCfg, err := LoadScopeConfig(emptyPath)
	if err != nil {
		t.Fatalf("LoadScopeConfig on empty file failed: %v", err)
	}
	if emptyCfg == nil {
		t.Fatal("expected non-nil ScopeConfig for empty file")
	}
}

func TestDeriveModuleScopes(t *testing.T) {
	anchors := []string{
		// Directory with 3 files: should NOT roll up
		"internal/core/pipeline/compact/a.go",
		"internal/core/pipeline/compact/b.go",
		"internal/core/pipeline/compact/c.go",

		// Directory with 2 files: should roll up to internal/core
		"internal/core/episode/store.go",
		"internal/core/episode/commit_linkage.go",

		// Directory with 3 files and snake_case naming: converts to kebab-case
		"internal/core/transcript_parser/parser.go",
		"internal/core/transcript_parser/ast.go",
		"internal/core/transcript_parser/token.go",

		// cmd directory with 3 files
		"cmd/repo-memory/main.go",
		"cmd/repo-memory/install.go",
		"cmd/repo-memory/status.go",

		// Symbol anchor with #
		"internal/core/ops/reader.go#ReadBatch",
		"internal/core/ops/writer.go#WriteBatch",
		"internal/core/ops/op.go#NewBatch",
	}

	modules := DeriveModuleScopes(anchors)
	if len(modules) == 0 {
		t.Fatal("expected derived module scopes, got none")
	}

	moduleByName := make(map[string]ModuleScope)
	for _, m := range modules {
		moduleByName[m.Name] = m
	}

	// 1. Check compact does not roll up
	compact, ok := moduleByName["core/pipeline/compact"]
	if !ok {
		t.Errorf("missing module core/pipeline/compact")
	} else if len(compact.PathGlobs) != 3 {
		t.Errorf("core/pipeline/compact: expected 3 path globs, got %d", len(compact.PathGlobs))
	}

	// 2. Check episode rolled up to core
	core, ok := moduleByName["core"]
	if !ok {
		t.Errorf("missing rolled up module core")
	} else {
		hasStore := false
		for _, g := range core.PathGlobs {
			if strings.Contains(g, "store.go") {
				hasStore = true
				break
			}
		}
		if !hasStore {
			t.Errorf("core module missing store.go: %v", core.PathGlobs)
		}
	}

	// 3. Check transcript_parser naming became core/transcript-parser
	tp, ok := moduleByName["core/transcript-parser"]
	if !ok {
		t.Errorf("missing module core/transcript-parser")
	} else if len(tp.PathGlobs) != 3 {
		t.Errorf("core/transcript-parser: expected 3 path globs, got %d", len(tp.PathGlobs))
	}

	// 4. Check cmd/repo-memory
	cmdMod, ok := moduleByName["cmd/repo-memory"]
	if !ok {
		t.Errorf("missing module cmd/repo-memory")
	} else if len(cmdMod.PathGlobs) != 3 {
		t.Errorf("cmd/repo-memory: expected 3 path globs, got %d", len(cmdMod.PathGlobs))
	}

	// 5. Check symbols extraction for core/ops
	opsMod, ok := moduleByName["core/ops"]
	if !ok {
		t.Errorf("missing module core/ops")
	} else {
		expectedSymbols := []string{"NewBatch", "ReadBatch", "WriteBatch"}
		if !reflect.DeepEqual(opsMod.Symbols, expectedSymbols) {
			t.Errorf("core/ops symbols: got %v, want %v", opsMod.Symbols, expectedSymbols)
		}
	}

	// 6. Check empty anchors
	if DeriveModuleScopes(nil) != nil {
		t.Errorf("DeriveModuleScopes(nil) should return nil")
	}
}

func TestBuildAliasMap_And_ResolveChain(t *testing.T) {
	tmpDir := t.TempDir()
	opsDir := filepath.Join(tmpDir, ".memory", "ops")
	writer := ops.NewWriter(opsDir)
	reader := ops.NewReader(opsDir)

	// Batch 1: split "core/storage" -> ["core/persistence", "core/kv"]
	batch1 := ops.NewBatch([]ops.Op{
		{
			Type:         ops.OpSplit,
			DossierScope: "core/storage",
			Fields: map[string]any{
				"new_dossiers": []string{"core/persistence", "core/kv"},
				"entry_moves":  map[string]string{"inv-01": "core/persistence"},
			},
		},
	})
	batch1.CreatedAt = time.Date(2026, 10, 1, 10, 0, 0, 0, time.UTC)
	if err := writer.Write(batch1); err != nil {
		t.Fatalf("failed to write batch 1: %v", err)
	}

	// Batch 2: split "core/persistence" -> ["persistence-and-sqlite"]
	batch2 := ops.NewBatch([]ops.Op{
		{
			Type:         ops.OpSplit,
			DossierScope: "core/persistence",
			Fields: map[string]any{
				"new_dossiers": []string{"persistence-and-sqlite"},
				"entry_moves":  map[string]string{"inv-01": "persistence-and-sqlite"},
			},
		},
	})
	batch2.CreatedAt = time.Date(2026, 10, 2, 10, 0, 0, 0, time.UTC)
	if err := writer.Write(batch2); err != nil {
		t.Fatalf("failed to write batch 2: %v", err)
	}

	aliasMap, err := BuildAliasMap(reader, context.Background())
	if err != nil {
		t.Fatalf("BuildAliasMap failed: %v", err)
	}

	// Check chain resolution: core/storage -> core/persistence -> persistence-and-sqlite
	if got := aliasMap.Resolve("core/storage"); got != "persistence-and-sqlite" {
		t.Errorf("Resolve(core/storage): got %q, want %q", got, "persistence-and-sqlite")
	}

	if got := aliasMap.Resolve("core/persistence"); got != "persistence-and-sqlite" {
		t.Errorf("Resolve(core/persistence): got %q, want %q", got, "persistence-and-sqlite")
	}

	// Non-aliased scope returns itself
	if got := aliasMap.Resolve("other-scope"); got != "other-scope" {
		t.Errorf("Resolve(other-scope): got %q, want %q", got, "other-scope")
	}

	// Check entry moves
	if got := aliasMap.EntryMoves["inv-01"]; got != "persistence-and-sqlite" {
		t.Errorf("EntryMoves[inv-01]: got %q, want %q", got, "persistence-and-sqlite")
	}
}

func TestAliasMap_Resolve_LoopPrevention(t *testing.T) {
	aliasMap := NewAliasMap()
	aliasMap.Aliases["A"] = "B"
	aliasMap.Aliases["B"] = "C"
	aliasMap.Aliases["C"] = "A"

	// Must terminate within max depth 10 without infinite loop or panic
	resolved := aliasMap.Resolve("A")
	if resolved == "" {
		t.Errorf("expected non-empty resolved string, got %q", resolved)
	}
}

func TestScopeResolver_ResolveScope(t *testing.T) {
	cfg := &ScopeConfig{
		Topics: []DeclaredScope{
			{
				Name:        "persistence-and-sqlite",
				Keywords:    []string{"sqlite", "persistence", "database"},
				Description: "Storage and concurrency",
			},
		},
		Externals: []DeclaredScope{
			{
				Name:        "antigravity-hooks",
				Keywords:    []string{"antigravity", "hooks"},
				ToolNames:   []string{"run_command", "view_file"},
				Description: "Tool hooks",
			},
		},
		Procedures: []DeclaredScope{
			{
				Name:        "flashing",
				Keywords:    []string{"flash", "burn"},
				Commands:    []string{"esptool.py", "pio run -t upload"},
				Description: "Firmware flashing procedures",
			},
		},
	}

	modules := []ModuleScope{
		{
			Name:      "core/transcript-parser",
			PathGlobs: []string{"internal/core/transcript_parser/parser.go"},
		},
		{
			Name:      "core",
			PathGlobs: []string{"internal/core/other.go"},
		},
		{
			Name:      "cmd/repo-memory",
			PathGlobs: []string{"cmd/repo-memory/main.go"},
		},
	}

	aliases := NewAliasMap()
	aliases.AddSplit("legacy-topic", []string{"persistence-and-sqlite"})
	aliases.AddSplit("old-mod", []string{"core/transcript-parser"})

	resolver := NewScopeResolver(cfg, modules, aliases)

	tests := []struct {
		name     string
		anchors  []string
		keywords []string
		want     string
	}{
		{
			name:     "alias direct match in anchors",
			anchors:  []string{"legacy-topic"},
			keywords: nil,
			want:     "persistence-and-sqlite",
		},
		{
			name:     "alias direct match in keywords",
			anchors:  nil,
			keywords: []string{"old-mod"},
			want:     "core/transcript-parser",
		},
		{
			name:     "anchor prefix matches specific module",
			anchors:  []string{"internal/core/transcript_parser/parser.go"},
			keywords: []string{"sqlite"}, // anchor should take precedence
			want:     "core/transcript-parser",
		},
		{
			name:     "anchor matches cmd module",
			anchors:  []string{"cmd/repo-memory/main.go"},
			keywords: nil,
			want:     "cmd/repo-memory",
		},
		{
			name:     "anchor matches general core module",
			anchors:  []string{"internal/core/other.go"},
			keywords: nil,
			want:     "core",
		},
		{
			name:     "keyword matches declared topic",
			anchors:  nil,
			keywords: []string{"sqlite"},
			want:     "persistence-and-sqlite",
		},
		{
			name:     "keyword matches declared external tool",
			anchors:  nil,
			keywords: []string{"run_command"},
			want:     "antigravity-hooks",
		},
		{
			name:     "keyword matches declared procedure command",
			anchors:  nil,
			keywords: []string{"esptool.py"},
			want:     "flashing",
		},
		{
			name:     "unmatched returns empty",
			anchors:  []string{"random/path.txt"},
			keywords: []string{"something-completely-unrelated"},
			want:     "",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := resolver.ResolveScope(tt.anchors, tt.keywords)
			if got != tt.want {
				t.Errorf("ResolveScope() = %q, want %q", got, tt.want)
			}
		})
	}
}

func TestScopeResolver_AllScopes_And_ScopeKind(t *testing.T) {
	cfg := &ScopeConfig{
		Topics: []DeclaredScope{
			{Name: "persistence-and-sqlite"},
		},
		Externals: []DeclaredScope{
			{Name: "antigravity-hooks"},
		},
		Procedures: []DeclaredScope{
			{Name: "flashing"},
		},
	}
	modules := []ModuleScope{
		{Name: "core/transcript-parser"},
		{Name: "cmd/repo-memory"},
	}
	aliases := NewAliasMap()
	aliases.AddSplit("legacy-scope", []string{"persistence-and-sqlite"})

	resolver := NewScopeResolver(cfg, modules, aliases)

	all := resolver.AllScopes()
	expected := []string{
		"antigravity-hooks",
		"cmd/repo-memory",
		"core/transcript-parser",
		"flashing",
		"legacy-scope",
		"persistence-and-sqlite",
	}

	if !reflect.DeepEqual(all, expected) {
		t.Errorf("AllScopes(): got %v, want %v", all, expected)
	}

	// Verify ScopeKind
	if got := resolver.ScopeKind("persistence-and-sqlite"); got != dossiers.DossierKindTopic {
		t.Errorf("ScopeKind(topic): got %v, want %v", got, dossiers.DossierKindTopic)
	}
	if got := resolver.ScopeKind("antigravity-hooks"); got != dossiers.DossierKindExternal {
		t.Errorf("ScopeKind(external): got %v, want %v", got, dossiers.DossierKindExternal)
	}
	if got := resolver.ScopeKind("flashing"); got != dossiers.DossierKindProcedure {
		t.Errorf("ScopeKind(procedure): got %v, want %v", got, dossiers.DossierKindProcedure)
	}
	if got := resolver.ScopeKind("core/transcript-parser"); got != dossiers.DossierKindModule {
		t.Errorf("ScopeKind(module): got %v, want %v", got, dossiers.DossierKindModule)
	}
}
